   454→/// Represents the ssz length bounds for RPC messages.
   455→#[derive(Debug, PartialEq)]
   456→pub struct RpcLimits {
   457→    pub min: usize,
   458→    pub max: usize,
   459→}
   460→
   461→impl RpcLimits {
   462→    pub fn new(min: usize, max: usize) -> Self {
   463→        Self { min, max }
   464→    }
   465→
   466→    /// Returns true if the given length is greater than `max_rpc_size` or out of
   467→    /// bounds for the given ssz type, returns false otherwise.
   468→    pub fn is_out_of_bounds(&self, length: usize, max_rpc_size: usize) -> bool {
   469→        length > std::cmp::min(self.max, max_rpc_size) || length < self.min
   470→    }
   471→}
