  1000→            RequestType::BlobsByRoot(req) => write!(f, "Blobs by root: {:?}", req),
  1001→            RequestType::DataColumnsByRoot(req) => write!(f, "Data columns by root: {:?}", req),
  1002→            RequestType::DataColumnsByRange(req) => {
